package com.wissfind.marketplace.controller; import com.wissfind.marketplace.entity.*;import com.wissfind.marketplace.repo.*;import com.wissfind.marketplace.service.CurrentUser;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/disputes") public class DisputeController {final DisputeRepository r;final OrderRepository o;public DisputeController(DisputeRepository r,OrderRepository o){this.r=r;this.o=o;} @GetMapping @PreAuthorize("hasAnyRole('ADMIN','SELLER')") public List<Dispute> all(){return r.findAll();} @PostMapping @PreAuthorize("hasRole('CUSTOMER')") public Dispute create(@RequestBody Dispute d){d.id=null;d.order=o.findById(d.order.id).orElseThrow();return r.save(d);} @PatchMapping("/{id}/respond") @PreAuthorize("hasAnyRole('SELLER','ADMIN')") public Dispute respond(@PathVariable Long id,@RequestBody Map<String,String> body){var d=r.findById(id).orElseThrow();d.response=body.get("response");d.status="RESPONDED";return r.save(d);}}
